import {lineCount} from './text-tools.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lessons=[
 {title:'한 문장으로 인물 소개',quote:'Call me Ishmael.',ko:'나를 이슈메일이라 불러 주시오.',author:'허먼 멜빌 · 모비 딕 (1851)',url:'https://www.gutenberg.org/files/15/15-h/15-h.htm',note:'이름만 건네도 목소리가 생깁니다. 성격을 설명하지 않고, 말투로 인물을 소개해 보세요.',steps:[['목소리','인물이 처음 건네는 말을 써 보세요. 누구에게 말하는지도 상상해 보세요.',3],['몸짓','방금 한 말과 어긋나는 몸짓을 보여 주세요. 감정의 이름은 쓰지 마세요.',5],['빈자리','인물이 끝내 말하지 않은 것을 독자가 짐작할 수 있게 마무리해 보세요.',3]]},
 {title:'첫 문장에 담긴 시선',quote:'It is a truth universally acknowledged',ko:'누구나 인정하는 진리가 있다.',author:'제인 오스틴 · 오만과 편견 (1813), 첫 문장 일부',url:'https://www.gutenberg.org/cache/epub/1342/pg1342-images.html',note:'단정하는 말에는 화자의 태도가 드러납니다. 모두가 믿는 규칙을 하나 만들고, 그 규칙을 흔들어 보세요.',steps:[['규칙','이 세계 사람들이 당연하게 여기는 일을 세 문장으로 적어 보세요.',3],['예외','그 규칙을 믿지 않는 인물을 등장시켜 보세요.',5],['선택','작은 사건 앞에서 그 인물이 어떻게 행동하는지 써 보세요.',5]]}
];
const lots={인물:['대답 대신 웃는 사람','기억을 잃은 편지 배달부','거짓말을 못하는 마법사','늘 한 정거장 먼저 내리는 사람','적의 이름을 잊지 못하는 기사','꿈속에서만 솔직한 연인'],장소:['폐관 직전의 도서관','비가 멈추지 않는 기차역','아무도 없는 기숙사 복도','두 세계가 겹치는 서점','해 뜨기 전의 옥상','시간이 느리게 흐르는 찻집'],사건:['보낸 적 없는 편지가 도착한다','상대의 목소리만 들리지 않는다','내일의 기억을 나눠 갖는다','단 한 번 이름을 바꿀 수 있다','헤어지려던 날 하루가 반복된다','잃어버린 물건이 상대의 방에서 발견된다']};
export function mountPractice(root,{owner,toast,onUse}){
 const key='galpi-practice-v2-'+owner;
 let data;try{data=JSON.parse(localStorage.getItem(key)||'null')}catch{}
 data||={lesson:0,step:0,texts:['','',''],history:[],draw:null,target:3};
 data.lesson=Math.min(lessons.length-1,Math.max(0,Number(data.lesson)||0));data.step=Math.min(2,Math.max(0,Number(data.step)||0));
 const save=()=>{try{localStorage.setItem(key,JSON.stringify(data));return true}catch{toast('연습장 저장 공간이 부족해요. 완성한 글을 파일로 내려받아 주세요.');return false}};
 const download=text=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='갈피-문장연습.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
 function render(){const l=lessons[data.lesson],step=l.steps[data.step];root.innerHTML=`<div class="page-heading"><div><p class="eyebrow">쓰는 연습</p><h1>한 문장부터.</h1><p class="sub">완성보다 관찰. 오늘은 짧게 써도 괜찮아요.</p></div><span class="date-stamp">연습 노트<br><strong>${new Date().toLocaleDateString('ko-KR')}</strong></span></div><div class="practice-tabs">${lessons.map((x,i)=>`<button class="chip ${i===data.lesson?'active':''}" data-lesson="${i}">${x.title}</button>`).join('')}</div><section class="quote-note"><div class="eyebrow">읽어 볼 문장</div><blockquote>${esc(l.ko)}</blockquote><p class="original-quote">${esc(l.quote)}</p><a href="${l.url}" target="_blank" rel="noopener">${esc(l.author)} ↗</a><small>공개 고전 원문 · 한국어는 갈피의 자체 번역</small><p>${esc(l.note)}</p></section><section class="practice-work"><div class="practice-steps">${l.steps.map((s,i)=>`<span class="${i===data.step?'current':''}">${i+1}. ${s[0]}</span>`).join('')}</div><div class="section-heading"><h2>${step[0]} 써 보기</h2><label class="inline-label">목표 <select id="practice-target">${[3,5,8,10].map(n=>`<option ${data.target===n?'selected':''}>${n}</option>`).join('')}</select>줄</label></div><p class="sub">${esc(step[1])}</p><textarea id="practice-text" class="practice-paper" maxlength="12000" aria-label="연습 원고" placeholder="한 문장씩, 줄을 바꾸며 써 보세요.">${esc(data.texts[data.step]||'')}</textarea><div class="practice-progress"><span id="practice-count"></span><span>빈 줄 제외 · Enter로 구분한 줄</span></div><progress id="practice-bar" max="${data.target}"></progress><p class="sub" id="practice-hint"></p><div class="actions"><button class="btn" id="practice-prev" ${data.step===0?'disabled':''}>이전 단계</button><button class="btn primary" id="practice-next">${data.step===2?'연습 마치기':'다음 단계 →'}</button><button class="text-btn" id="practice-download">TXT 저장</button></div></section><section class="lottery"><div class="section-heading"><div><p class="eyebrow">막힐 때 꺼내 보는</p><h2>소재 제비뽑기</h2></div><button class="btn" id="draw-lot">다시 뽑기 ↻</button></div><div class="lot-cards">${Object.keys(lots).map((k,i)=>`<div><small>0${i+1} / ${k}</small><p>${esc(data.draw?.[k]||'아직 펼치지 않은 제비')}</p></div>`).join('')}</div><p class="sub">${data.draw?'세 가지를 연결해 첫 만남을 써 보세요. 반드시 모두 사용할 필요는 없어요.':'뽑기를 누르면 인물·장소·사건을 하나씩 조합해 드려요.'}</p></section><section><div class="section-heading"><h2>마친 연습 <span class="count">${data.history.length}</span></h2><span class="sub">이 브라우저에 보관 · 최근 20개</span></div>${data.history.map((h,i)=>`<details class="practice-history"><summary>${esc(h.title)} <span>${esc(h.date)}</span></summary><p>${esc(h.text)}</p><button class="btn small" data-use="${i}">새 원고로 가져가기</button></details>`).join('')||'<p class="sub">세 단계를 마치면 이곳에 모아 둡니다.</p>'}</section>`;
 const q=s=>root.querySelector(s),text=q('#practice-text');
 function update(){const n=lineCount(text.value);q('#practice-count').textContent=`${n} / ${data.target}줄 · ${Array.from(text.value).length.toLocaleString()}자`;q('#practice-bar').value=n;q('#practice-next').disabled=n<data.target;q('#practice-hint').textContent=n>=data.target?'목표를 채웠어요. 장면이 전달된다면 다음 단계로 넘어가도 좋아요.':`목표까지 ${data.target-n}줄. 줄 수는 연습을 위한 기준이지 좋은 문장의 조건은 아니에요.`}
 text.oninput=()=>{data.texts[data.step]=text.value;save();update()};q('#practice-target').onchange=e=>{data.target=+e.target.value;save();update()};update();
 q('#practice-prev').onclick=()=>{data.step--;data.target=l.steps[data.step][2];save();render()};
 q('#practice-next').onclick=()=>{if(lineCount(text.value)<data.target)return;if(data.step<2){data.step++;data.target=l.steps[data.step][2]}else{data.history.unshift({title:l.title,date:new Date().toLocaleDateString('ko-KR'),text:data.texts.join('\n\n')});data.history=data.history.slice(0,20);data.texts=['','',''];data.step=0;data.target=l.steps[0][2];toast('연습 한 편을 저장했어요.')}save();render()};
 q('#practice-download').onclick=()=>download(data.texts.join('\n\n'));
 q('#draw-lot').onclick=()=>{data.draw=Object.fromEntries(Object.entries(lots).map(([k,values])=>[k,values[Math.floor(Math.random()*values.length)]]));save();render()};
 root.querySelectorAll('[data-lesson]').forEach(el=>el.onclick=()=>{if(+el.dataset.lesson===data.lesson)return;if(data.texts.some(t=>t.trim())){data.history.unshift({title:lessons[data.lesson].title+' · 진행 중 보관',date:new Date().toLocaleDateString('ko-KR'),text:data.texts.join('\n\n')});data.history=data.history.slice(0,20)}data.lesson=+el.dataset.lesson;data.step=0;data.texts=['','',''];data.target=lessons[data.lesson].steps[0][2];save();render()});
 root.querySelectorAll('[data-use]').forEach(el=>el.onclick=()=>onUse(data.history[+el.dataset.use]));
 }
 render();
}
